    [437868] = { en = "$s1 Shadow damage inflicted every $t1 sec.\r\nDamage done reduced by $s2%.", description = "Infligge $s1 danni da ombra ogni $t1 sec.\r\nDanni inflitti ridotti del $s2%." },
    [437902] = { en = "$@spellaura", description = "$@spellaura" },
