    [438537] = { en = "Increases critical strike chance of spells by $s1%, grants $s2 spell damage and healing, and increases melee and ranged attack speed by $s4%. 120 minute duration.", description = "Aumenta del $s1% la probabilità di critico degli incantesimi, fornisce $s2 danni magici e cure e aumenta del $s4% la velocità d'attacco in mischia e a distanza. Dura 120 minuti." },
    [438551] = { en = "More danger, more rewards!", description = "Più pericoli, più ricompense!" },
    [438715] = { en = "Flames spill forth from the mechanical furnace.", description = "Le fiamme fuoriescono dalla fornace meccanica." },
    [438727] = { en = "Nature damage taken increased by $w1%.", description = "I danni da Natura subiti aumentano del $w1%." },
    [439155] = { en = "Empowered by Innovation. Dealing up to $s1 increased damage and healing with spells, and increasing attack power by increased $s2.", description = "Potenziato dall'Innovazione. Infligge fino a $s1 danni aggiuntivi e fornisce cure aggiuntive con gli incantesimi, aumentando la potenza d'attacco di $s2." },
    [439733] = { en = "Immune to Polymorph effects.\r\nReduces mana cost of heal over time spells by $439734s1%.\r\nIncreases Spirit by $439734s2% and armor by $439734s3%.\r\nIncreases healing received by $439745s1% for all party members within $439745a1 yards and healing done by Wild Growth by $439734s8%.", description = "Immune agli effetti di Polymorph.\r\nRiduce del $439734s1% il costo in mana degli incantesimi di cura periodica.\r\nAumenta del $439734s2% lo Spirito e del $439734s3% l'armatura.\r\nAumenta del $439745s1% le cure ricevute da tutti i membri del gruppo entro $439745a1 metri e del $439734s8% le cure generate da Wild Growth." },
    [439753] = { en = "You summon a flurry of stars from the sky on all targets within 30 yards of the caster, each dealing $50288s1 Arcane damage. Also causes $50294s1 Arcane damage to all other enemies within $50294a1 yards of the enemy target. Maximum 20 stars. Lasts $48505d.", description = "Richiami dal cielo una pioggia di stelle su tutti i bersagli entro 30 metri dall'incantatore, ognuna delle quali infligge $50288s1 danni Arcani. Infligge inoltre $50294s1 danni Arcani a tutti gli altri nemici entro $50294a1 metri dal bersaglio nemico. Massimo 20 stelle. Dura $48505d." },
    [439756] = { en = "Maximum 20 stars. Lasts $48505d.", description = "Massimo 20 stelle. Dura $48505d." },
    [439959] = { en = "Magical damage dealt by spells and abilities is increased by up to $s1.", description = "I danni magici inflitti da incantesimi e abilità aumentano fino a $s1." },
    [440114] = { en = "You may use Execute once regardless of target's health and you will have $440113s2 Rage remaining afterward.", description = "Puoi usare Execute una volta indipendentemente dalla salute del bersaglio e al termine ti resteranno $440113s2 punti Rabbia." },
    [440651] = { en = "Absorbs damage and increases the casting paladin's chance to critically hit with Flash of Light by $s2%.", description = "Assorbe i danni e aumenta di $s2% la probabilità del paladino che lancia l'incantesimo di infliggere un colpo critico con Lampo di Luce." },
    [440667] = { en = "Attack Power reduced by $w1.", description = "Potenza d'attacco ridotta di $w1." },
    [440668] = { en = "Attack Power increased by $w1%.", description = "Potenza d'attacco aumentata del $w1%." },
    [440882] = { en = "Magical damage taken is reduced by $w1%.", description = "I danni magici subiti sono ridotti del $w1%." },
    [442211] = { en = "Immune to Fear effects.\r\nRage and energy costs reduced.\r\nMangle hits multiple targets.", description = "Immune agli effetti di Paura.\r\nCosti in Rabbia ed energia ridotti.\r\nMangle colpisce più bersagli." },
    [442222] = { en = "$s2% increased damage taken from $@spellname433251.", description = "Danni subiti aumentati del $s2% da $@spellname433251." },
    [442223] = { en = "$s2% increased damage taken from $@spellname433251.", description = "Danni subiti aumentati del $s2% da $@spellname433251." },
    [442225] = { en = "$s2% increased damage taken from $@spellname433251.", description = "Danni subiti aumentati del $s2% da $@spellname433251." },
    [443278] = { en = "Chance to embed a seed into enemy humanoids, beasts, or dragonkin hit by your abilities or spells.", description = "Possibilità di conficcare un seme negli umanoidi, nelle bestie o nei draghi nemici colpiti dalle tue abilità o dai tuoi incantesimi." },
    [443320] = { en = "Physical$?$w3>0[, Fire, Frost, and Nature][] damage done increased by $s1% and all threat generated reduced by $s2%.", description = "Danni fisici$?$w3>0[, da fuoco, gelo e natura][] inflitti aumentati del $s1% e tutta la minaccia generata ridotta del $s2%." },
    [443369] = { en = "Chronomantic energy ready to be unleashed. Instantly healing a friendly target for ${$<healpower>*$436517m1/100} to ${$<healpower>*$436517M1/100}.", description = "L'energia cronormantica è pronta per essere scatenata. Cura istantaneamente un bersaglio amico da ${$<healpower>*$436517m1/100} a ${$<healpower>*$436517M1/100}." },
    [443678] = { en = "Will grow a Healing Blossom from corpse when killed.", description = "Alla morte farà crescere un Fiore Curativo dal cadavere." },
    [443917] = { en = "Restoring $s1% of maximum mana every $t1 sec.", description = "Ripristina il $s1% del mana massimo ogni $t1 s." },
    [443975] = { en = "$s1 Shadow damage inflicted every $t1 sec.\r\nAttack, cast, and movement speed reduced by $s2%.", description = "Infligge $s1 danni d'Ombra ogni $t1 s.\r\nVelocità d'attacco, di lancio e di movimento ridotte del $s2%." },
